// Component One node of an application's deploy workflow (a DAG step). Edges are
// expressed by each node's depends_on. The secret-bearing config (the Helm
// `values` override) is redacted for callers below editor.
type Component struct {
	// ChartCredentialId Optional credential for pulling a private chart.
	ChartCredentialId *openapi_types.UUID `json:"chart_credential_id,omitempty"`

	// Config Type-specific, non-secret parameters (helm: chart_source/repo_url/
	// chart/version/git_ref/git_path/values/…; manifest: repo_url/git_ref/
	// path; terraform: repo_url/git_ref/path/backend/backend_config/
	// cloud_credential_id). An OpenTofu component is a single
	// node: it runs `plan` then, once approved (see requires_approval),
	// `apply` — the run expands it into those two steps, so `command` is
	// not authored. `tofu_version` optionally selects the OpenTofu
	// release line the component runs (e.g. `1.12`; empty runs the
	// platform default line). The state backend is managed by Spacefleet
	// (the run writes a backend override into the module, so state lands
	// where this config says regardless of any backend block in code):
	// `backend` must be `s3` (the only supported type today) and
	// `backend_config` is a JSON object of its settings —
	// `bucket`/`key`/`region` required; `dynamodb_table`, `encrypt`, and
	// `kms_key_id` optional. State locking: on OpenTofu 1.10+ the run
	// locks state natively in S3 automatically (no setup; set
	// `use_lockfile` explicitly in `backend_config` only to override
	// that, and only on 1.10+). On older lines, name a `dynamodb_table`
	// — when a cloud credential is attached, Spacefleet creates the
	// table if it doesn't exist.
	// `cloud_credential_id` is the UUID of an AWS cloud credential the run
	// signs in with (state backend + the module's AWS providers); empty
	// uses the runner's own role.
	// `auth_cluster_id` optionally attaches **cluster authentication**:
	// the UUID of a registered cluster the run prepares ready-to-use
	// Kubernetes authentication for. The run mounts a connection file for
	// that cluster and points the standard `KUBE_CONFIG_PATH` environment
	// variable at it, so Kubernetes-backed providers (kubernetes, helm,
	// kubectl) in the module authenticate without any provider
	// configuration in code. This is not a deploy target —
	// `target_cluster_id` stays null for terraform.
	// `init_flags`/`plan_flags`/`apply_flags` are optional JSON arrays of
	// extra CLI flag tokens appended to `tofu init`/`plan`/`apply` (one whole
	// argument per element, e.g. `["-var=env=prod","-target=aws_instance.web"]`);
	// since `apply` applies the plan step's saved plan, plan-time flags
	// (`-var`/`-var-file`/`-target`) go in `plan_flags`, not `apply_flags`.
	// The `values` and `backend_config` keys are redacted for callers below
	// editor.
	Config map[string]string `json:"config"`

	// ContinueOnFailure When true, a failure of this node does not skip its dependents or
	// fail the run (the run settles "partial" instead).
	ContinueOnFailure bool `json:"continue_on_failure"`

	// DependsOn Ids of sibling components this node waits on.
	DependsOn []openapi_types.UUID `json:"depends_on"`

	// GithubInstallationId Optional GitHub App installation for a private git source.
	GithubInstallationId *openapi_types.UUID `json:"github_installation_id,omitempty"`

	// GroupId Id of the explicit group container this component is a parallel
	// member of, or null when ungrouped. A node that depends on a group
	// waits for all of its members.
	GroupId *openapi_types.UUID `json:"group_id,omitempty"`
	Id      openapi_types.UUID  `json:"id"`
	Name    string              `json:"name"`

	// Position Canvas coordinates {x, y} for the workflow builder UI.
	Position *map[string]float32 `json:"position,omitempty"`

	// RequiresApproval When true, the run parks at this node (status awaiting_approval)
	// until a human approves it; the node only runs once approved. Used to
	// gate destructive or sensitive steps (e.g. an OpenTofu apply).
	RequiresApproval *bool `json:"requires_approval,omitempty"`

	// TargetClusterId The cluster this component deploys into. Required for helm and
	// manifest components; null for terraform (which has no cluster
	// target).
	TargetClusterId *openapi_types.UUID `json:"target_cluster_id,omitempty"`

	// TargetNamespace The namespace this component deploys into. Required for helm;
	// unused for manifest (manifests carry their own namespaces) and
	// terraform.
	TargetNamespace *string `json:"target_namespace,omitempty"`

	// Type The kind of step a workflow component runs.
	Type ComponentType `json:"type"`
}

// ComponentGroup An explicit group container in an application's deploy workflow — a named
// box holding components that run in parallel. A node that depends on the
// group waits for all of its members (all-must-complete); a group's
